/// How much attention something deserves.
///
/// One scale for errors and for notifications, deliberately: a reader
/// deciding whether to open a notification and an operator deciding
/// whether to wake somebody are grading the same axis, and two
/// vocabularies for one judgement is how they drift apart.
///
/// **Least severe first, because the derived `Ord` is the scale.**
/// Written the other way round, `Severity::Critical > Severity::Info`
/// was `false` and `.max()` answered `Info`: the obvious paging filter,
/// `severity() >= Severity::Error`, kept `IdsNameTooLong` and dropped
/// `JournalChainBroken` — the code that means the audit chain is
/// broken. Declaration order *is* the comparison for a derived `Ord`,
/// so the list below is the ranking and reordering it changes what
/// every comparison in the platform means.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Severity {
    /// Worth recording, nothing failed.
    Info,
    /// The operation continued, degraded.
    Warning,
    /// The operation failed.
    Error,
    /// Something a person should be woken for.
    Critical,
}

impl Severity {
    /// The word the registry, the ledger and the pages write.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Info => "info",
            Self::Warning => "warning",
            Self::Error => "error",
            Self::Critical => "critical",
        }
    }
}

impl core::fmt::Display for Severity {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        formatter.write_str(self.as_str())
    }
}

